    @classmethod
    def get_icon_svg(cls, name: str, size: float = 16, color: str = "#ffffff", stroke_width: float = 2.0) -> str:
        key = (name or "info").lower().replace("_", "-")
        path = cls.ICONS.get(key, cls.ICONS.get("info"))
        return f'''<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="{color}" stroke-width="{stroke_width}" stroke-linecap="round" stroke-linejoin="round">{path}</svg>'''
